//go:build e2e

package tests

import (
	"context"
	"testing"
	"time"

	"github.com/entireio/cli/e2e/testutil"
)

// TestMidTurnCommit_DifferentFilesThanPreviousTurn: Turn 1 creates file A
// (tracked via Stop checkpoint), Turn 2 creates+commits different files B,C.
// Validates that the mid-turn commit gets a checkpoint on entire/checkpoints/v1
// even though the committed files (B,C) don't overlap with Turn 1's tracked
// files (A).
//
// This is a regression test for the bug where shouldCondenseWithOverlapCheck
// skipped condensation for ACTIVE sessions because filesTouchedBefore (from
// Turn 1) didn't overlap with the committed files (from Turn 2).
//
// Category: agent-validation — this test validates hook behavior that varies
// by agent (commit flow, hook timing). It should run for every new agent
// integration, not just as a one-time regression check.
// TODO: when we split E2E tests into "always run" vs "new agent validation",
// this belongs in the "new agent validation" category.
func TestMidTurnCommit_DifferentFilesThanPreviousTurn(t *testing.T) {
	testutil.ForEachAgent(t, 4*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		// Turn 1: Agent creates a file (tracked as touched). No commit.
		_, err := s.RunPrompt(t, ctx,
			"create a markdown file at docs/turn1.md with a paragraph about apples. Do not commit the file. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent prompt 1 (turn 1) failed: %v", err)
		}
		testutil.AssertFileExists(t, s.Dir, "docs/turn1.md")

		// Turn 2: Agent creates DIFFERENT files and commits them mid-turn.
		// The committed files (turn2a.md, turn2b.md) do NOT overlap with
		// Turn 1's tracked files (turn1.md).
		_, err = s.RunPrompt(t, ctx,
			"create two markdown files: docs/turn2a.md about bananas and docs/turn2b.md about cherries. Then git add and git commit both files with a short message. Do not commit any other files. Do not ask for confirmation, just make the changes. Do not use worktrees.")
		if err != nil {
			t.Fatalf("agent prompt 2 (turn 2) failed: %v", err)
		}
		testutil.AssertFileExists(t, s.Dir, "docs/turn2a.md")
		testutil.AssertFileExists(t, s.Dir, "docs/turn2b.md")

		// The agent committed mid-turn, so there should be at least 1 new commit.
		testutil.AssertNewCommits(t, s, 1)

		// CRITICAL: The mid-turn commit should have triggered condensation
		// to entire/checkpoints/v1, even though committed files differ from
		// Turn 1's tracked files. This is the regression assertion.
		testutil.WaitForCheckpoint(t, s, 30*time.Second)
		testutil.AssertCheckpointAdvanced(t, s)

		cpID := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		testutil.AssertCheckpointExists(t, s.Dir, cpID)
		testutil.WaitForNoShadowBranches(t, s.Dir, 10*time.Second)
	})
}
//go:build e2e

package tests

import (
	"context"
	"os"
	"path/filepath"
	"testing"
	"time"

	"github.com/entireio/cli/e2e/testutil"
	"github.com/stretchr/testify/assert"
)

// TestHumanOnlyChangesAndCommits: human creates a file and commits without any
// agent interaction. No checkpoint should be created.
func TestHumanOnlyChangesAndCommits(t *testing.T) {
	testutil.ForEachAgent(t, 1*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		// Create a file and commit entirely as a human — no agent prompt.
		if err := os.MkdirAll(filepath.Join(s.Dir, "docs"), 0o755); err != nil {
			t.Fatalf("mkdir: %v", err)
		}
		if err := os.WriteFile(filepath.Join(s.Dir, "docs", "human.md"), []byte("# Written by a human\n"), 0o644); err != nil {
			t.Fatalf("write file: %v", err)
		}

		s.Git(t, "add", "docs/")
		s.Git(t, "commit", "-m", "Human-only commit")

		// Give the post-commit hook time to fire (if it were going to).
		time.Sleep(5 * time.Second)

		testutil.AssertCheckpointNotAdvanced(t, s)

		trailer := testutil.GetCheckpointTrailer(t, s.Dir, "HEAD")
		assert.Empty(t, trailer, "human-only commit should not have checkpoint trailer")
	})
}

// TestSingleSessionManualCommit: one prompt creates a file, user commits manually.
func TestSingleSessionManualCommit(t *testing.T) {
	testutil.ForEachAgent(t, 2*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		_, err := s.RunPrompt(t, ctx,
			"create a markdown file at docs/red.md with a paragraph about the colour red. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent failed: %v", err)
		}

		s.Git(t, "add", ".")
		s.Git(t, "commit", "-m", "Add md file about red")

		testutil.AssertFileExists(t, s.Dir, "docs/*.md")
		testutil.AssertNewCommits(t, s, 1)

		testutil.WaitForCheckpoint(t, s, 30*time.Second)
		testutil.AssertCheckpointAdvanced(t, s)

		cpID := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		testutil.AssertCheckpointExists(t, s.Dir, cpID)
		testutil.AssertCheckpointMetadataComplete(t, s.Dir, cpID)
		testutil.WaitForNoShadowBranches(t, s.Dir, 10*time.Second)
	})
}

// TestSingleSessionAgentCommitInTurn: one prompt creates a file and commits it.
// Expects both an initial checkpoint (post-commit) and a catchup checkpoint
// (end-of-turn) referencing the same checkpoint ID.
func TestSingleSessionAgentCommitInTurn(t *testing.T) {
	testutil.ForEachAgent(t, 2*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		_, err := s.RunPrompt(t, ctx,
			"create a markdown file at docs/red.md with a paragraph about the colour red, then commit it. Do not ask for confirmation, just make the change.")
		if err != nil {
			t.Fatalf("agent failed: %v", err)
		}

		testutil.AssertFileExists(t, s.Dir, "docs/*.md")

		testutil.WaitForCheckpoint(t, s, 30*time.Second)
		testutil.AssertCheckpointAdvanced(t, s)

		cpID := testutil.AssertHasCheckpointTrailer(t, s.Dir, "HEAD")
		testutil.AssertCheckpointExists(t, s.Dir, cpID)
		testutil.AssertCheckpointInLastN(t, s.Dir, cpID, 2)
		testutil.WaitForNoShadowBranches(t, s.Dir, 10*time.Second)
	})
}

// TestSingleSessionSubagentCommitInTurn: one prompt with subagent creates a file and commits it.
// Expects both an initial checkpoint (post-commit) and a catchup checkpoint
// (end-of-turn) referencing the same checkpoint ID.
func TestSingleSessionSubagentCommitInTurn(t *testing.T) {
	testutil.ForEachAgent(t, 2*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		if s.Agent.Name() == "copilot-cli" {
			t.Skip("copilot-cli may run prompt-mode subagents in the background while the foreground process returns and fires agent-stop/session-end hooks first; when the later subagent commit happens, git hooks see no active session, so this same-turn subagent-commit assertion is not stable for Copilot")
		}

		_, err := s.RunPrompt(t, ctx,
			"use a subagent: create a markdown file at docs/red.md with a paragraph about the colour red, then commit it. Run the subagent in the foreground and wait for it to finish; never run it in the background. Do not ask for confirmation, just make the change.")
		if err != nil {
