package testutil

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/execx"
	"github.com/entireio/cli/e2e/agents"
	"github.com/entireio/cli/e2e/entire"
)

const droidRepoSettingsPath = ".factory/settings.json"

const (
	checkpointRefV1 = "entire/checkpoints/v1"
)

// RepoState holds the working state for a single test's cloned repository.
type RepoState struct {
	Agent            agents.Agent
	Dir              string
	ArtifactDir      string
	HeadBefore       string
	CheckpointBefore string
	ConsoleLog       *os.File
	session          agents.Session // interactive session, if started via StartSession
	skipArtifacts    bool           // suppresses artifact capture on scenario restart
}

// SetupRepo creates a fresh git repository in a temporary directory, seeds it
// with an initial commit, and runs `entire enable` for the given agent.
// Artifact capture is registered as a cleanup function.
//
// When E2E_KEEP_REPOS is set, the temporary directory is not cleaned up
// so it can be inspected after the test. A symlink in the artifact dir
// points to the preserved repo.
func SetupRepo(t *testing.T, agent agents.Agent) *RepoState {
	t.Helper()

	keepRepos := os.Getenv("E2E_KEEP_REPOS") != ""

	// Always use os.MkdirTemp instead of t.TempDir(). Go's t.TempDir()
	// creates nested subdirectories (TestName.../001/) whose structure
	// confuses some agents' (e.g. opencode) working-directory resolution.
	//
	// Codex refuses to operate from /tmp (e.g. "Refusing to create helper
	// binaries under temporary dir"), so for codex we place the repo under
	// $HOME/.cache/entire-e2e-repos/ instead.
	root := ""
	if agent.Name() == "codex" {
		cache, cerr := os.UserCacheDir()
		if cerr != nil {
			t.Fatalf("resolve user cache dir: %v", cerr)
		}
		root = filepath.Join(cache, "entire-e2e-repos")
		if err := os.MkdirAll(root, 0o755); err != nil {
			t.Fatalf("create e2e repo root %q: %v", root, err)
		}
	}
	dir, err := os.MkdirTemp(root, "e2e-repo-*")
	if err != nil {
		t.Fatalf("create temporary e2e repo under %q: %v", root, err)
	}
	if keepRepos {
		t.Logf("E2E_KEEP_REPOS: repo will be preserved at %s", dir)
	} else {
		t.Cleanup(func() { os.RemoveAll(dir) })
	}

	// Resolve symlinks (macOS: /var -> /private/var) so paths match
	// what agent CLIs see when they resolve their own CWD.
	if resolved, err := filepath.EvalSymlinks(dir); err == nil {
		dir = resolved
	}

	Git(t, dir, "init")
	Git(t, dir, "config", "user.name", "E2E Test")
	Git(t, dir, "config", "user.email", "e2e@test.local")
	Git(t, dir, "config", "core.pager", "cat")
	Git(t, dir, "config", "core.autocrlf", "true")
	Git(t, dir, "commit", "--allow-empty", "-m", "initial commit")

	// External agents need external_agents enabled in settings before enable,
	// so the CLI can discover the agent binary via PATH during DiscoverAndRegister.
	if ea, ok := agent.(agents.ExternalAgent); ok && ea.IsExternalAgent() {
		entireDir := filepath.Join(dir, ".entire")
		if err := os.MkdirAll(entireDir, 0o755); err != nil {
			t.Fatalf("create .entire for external agent: %v", err)
		}
		if err := os.WriteFile(filepath.Join(entireDir, "settings.json"),
			[]byte("{\"external_agents\": true}\n"), 0o644); err != nil {
			t.Fatalf("write external_agents setting: %v", err)
		}
	}

	entire.Enable(t, dir, agent.EntireAgent())
	if agent.Name() == "gemini-cli" {
		setupGeminiTestHome(t, dir)
	}
	if agent.Name() == "factoryai-droid" {
		if err := configureDroidRepoSettings(dir); err != nil {
			t.Fatalf("configure droid repo settings: %v", err)
		}
	}
	// commit_linking=always ensures the prepare-commit-msg hook adds the
	// Entire-Checkpoint trailer unconditionally. This is needed because
	// interactive agents run inside tmux (CanPromptInteractively()=true) but
	// can't respond to prompts, and content detection may fail on the first
	// checkpoint when no shadow branch exists yet. Prompt-mode agents still
	// exercise the !CanPromptInteractively() fast path since they have no TTY
	// regardless of this setting.
	PatchSettings(t, dir, map[string]any{"log_level": "debug", "commit_linking": "always"})

	// Copilot CLI blocks on a "No copilot instructions found" notice in fresh
	// repos that lack .github/copilot-instructions.md, preventing the interactive
	// prompt from appearing.
	if agent.Name() == "copilot-cli" {
		ghDir := filepath.Join(dir, ".github")
		if err := os.MkdirAll(ghDir, 0o755); err != nil {
			t.Fatalf("create .github dir: %v", err)
		}
		if err := os.WriteFile(filepath.Join(ghDir, "copilot-instructions.md"), []byte("# E2E Test\n"), 0o644); err != nil {
			t.Fatalf("write copilot-instructions.md: %v", err)
		}
	}

	// OpenCode's non-interactive mode auto-rejects external_directory permission
	// since there's no user to prompt. Write a config to allow it.
	if agent.Name() == "opencode" {
		cfg := `{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}}`
		if key := os.Getenv("ANTHROPIC_API_KEY"); key != "" {
			cfg = fmt.Sprintf(`{"$schema": "https://opencode.ai/config.json", "permission": {"external_directory": "allow"}, "provider": {"anthropic": {"options": {"apiKey": %q}}}}`, key)
		}
		if err := os.WriteFile(filepath.Join(dir, "opencode.json"), []byte(cfg+"\n"), 0o644); err != nil {
			t.Fatalf("write opencode.json: %v", err)
		}
	}

	// Create artifact dir eagerly so console.log is written to disk
	// incrementally. Even if the test is killed by a global timeout,
	// partial output survives.
	artDir := artifactDir(t)
	consoleLog, err := os.Create(filepath.Join(artDir, "console.log"))
	if err != nil {
		t.Fatalf("create console.log: %v", err)
	}

	state := &RepoState{
		Agent:            agent,
		Dir:              dir,
		ArtifactDir:      artDir,
		HeadBefore:       GitOutput(t, dir, "rev-parse", "HEAD"),
		CheckpointBefore: CheckpointState(dir),
		ConsoleLog:       consoleLog,
	}

	t.Cleanup(func() {
		_ = consoleLog.Close()
		if !state.skipArtifacts {
			CaptureArtifacts(t, state)
		}
	})

	return state
}

func checkpointReadRef() string {
	return checkpointRefV1
}

// CurrentCheckpointRef returns the current committed-checkpoint state used for
// advance detection in the active suite mode: the v1 branch hash (git-branch) or
// the per-checkpoint-ref digest (git-refs). Pair it with WaitForCheckpointAdvanceFrom.
func CurrentCheckpointRef(t *testing.T, dir string) string {
	t.Helper()
	if UsingGitRefs() {
		return CheckpointState(dir)
	}
	return GitOutput(t, dir, "rev-parse", checkpointReadRef())
}

// PushCheckpointRefs pushes the committed checkpoint refs to the origin remote.
// Remote-resume tests use this instead of hardcoding v1 branch pushes.
func PushCheckpointRefs(t *testing.T, dir string) {
	t.Helper()

	if UsingGitRefs() {
		Git(t, dir, "push", "origin", checkpointRefPrefix+"*:"+checkpointRefPrefix+"*")
		return
	}
	Git(t, dir, "push", "origin", checkpointRefV1+":"+checkpointRefV1)
}

func setupGeminiTestHome(t *testing.T, repoDir string) {
	t.Helper()

	homeDir := geminiTestHomeDir(repoDir)
	t.Cleanup(func() {
		if err := os.RemoveAll(homeDir); err != nil {
			t.Errorf("remove gemini test home: %v", err)
		}
	})

	geminiDir := filepath.Join(homeDir, ".gemini")
	if err := os.MkdirAll(filepath.Join(geminiDir, "acknowledgments"), 0o755); err != nil {
		t.Fatalf("create gemini test home: %v", err)
	}

	config := `{"security":{"auth":{"selectedType":"gemini-api-key"}}}`
	if err := os.WriteFile(filepath.Join(geminiDir, "settings.json"), []byte(config), 0o644); err != nil {
		t.Fatalf("write gemini settings: %v", err)
	}
}

func geminiTestHomeDir(repoDir string) string {
	return filepath.Join(filepath.Dir(repoDir), filepath.Base(repoDir)+"-gemini-home")
}

func configureDroidRepoSettings(repoDir string) error {
	home, err := os.UserHomeDir()
	if err != nil {
		return fmt.Errorf("get home dir: %w", err)
	}

	globalSettingsPath := filepath.Join(home, ".factory", "settings.json")
	repoSettingsPath := filepath.Join(repoDir, droidRepoSettingsPath)

	if err := mergeDroidCustomModels(globalSettingsPath, repoSettingsPath); err != nil {
		return err
	}
	if err := ensureGitInfoExcludeContains(repoDir, droidRepoSettingsPath); err != nil {
		return fmt.Errorf("exclude droid settings from git: %w", err)
		return fmt.Errorf("exclude droid settings from git: %w", err)
	}
	return nil
}

func mergeDroidCustomModels(globalSettingsPath, repoSettingsPath string) error {
	globalSettings, err := loadJSONMap(globalSettingsPath, "global droid settings")
	if err != nil {
		return err
	}

	customModels, ok := globalSettings["customModels"]
	if !ok {
		return fmt.Errorf(
			"global droid settings at %s missing customModels; repo-local %s shadows global settings",
			globalSettingsPath,
			repoSettingsPath,
		)
	}

	var models []json.RawMessage
	if err := json.Unmarshal(customModels, &models); err != nil {
		return fmt.Errorf("parse customModels in %s: %w", globalSettingsPath, err)
	}
	if len(models) == 0 {
		return fmt.Errorf("global droid settings at %s has empty customModels", globalSettingsPath)
	}

	repoSettings, err := loadJSONMap(repoSettingsPath, "repo-local droid settings")
	if err != nil {
		return err
	}
	repoSettings["customModels"] = customModels

	// Set the active custom model so interactive mode uses the BYOK model
	// instead of prompting for selection. The value must match the Model
	// field from the customModels entry (not the displayName).
	modelJSON, err := json.Marshal(agents.DefaultDroidModel())
	if err != nil {
		return fmt.Errorf("marshal model setting: %w", err)
	}
	repoSettings["model"] = json.RawMessage(modelJSON)

	// High autonomy prevents Droid from asking for confirmation during
	// interactive E2E tests, which would cause hangs waiting for input.
	repoSettings["autonomyMode"] = json.RawMessage(`"auto-high"`)
	repoSettings["completionSound"] = json.RawMessage(`"off"`)

	out, err := json.MarshalIndent(repoSettings, "", "  ")
	if err != nil {
		return fmt.Errorf("marshal repo-local droid settings: %w", err)
	}
	out = append(out, '\n')

	if err := os.WriteFile(repoSettingsPath, out, 0o600); err != nil {
		return fmt.Errorf("write repo-local droid settings %s: %w", repoSettingsPath, err)
	}
	return nil
}

func loadJSONMap(path, description string) (map[string]json.RawMessage, error) {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("read %s at %s: %w", description, path, err)
	}

	var parsed map[string]json.RawMessage
	if err := json.Unmarshal(data, &parsed); err != nil {
		return nil, fmt.Errorf("parse %s at %s: %w", description, path, err)
	}
	if parsed == nil {
		parsed = make(map[string]json.RawMessage)
	}
	return parsed, nil
}

func ensureGitInfoExcludeContains(repoDir, entry string) error {
	excludePath := filepath.Join(repoDir, ".git", "info", "exclude")

	data, err := os.ReadFile(excludePath)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("read %s: %w", excludePath, err)
	}

	normalized := strings.ReplaceAll(string(data), "\r\n", "\n")
	for _, line := range strings.Split(normalized, "\n") {
		if strings.TrimSpace(line) == entry {
			return nil
		}
	}

	var b strings.Builder
	if len(data) > 0 {
		b.Write(data)
		if data[len(data)-1] != '\n' {
			b.WriteByte('\n')
		}
	}
	b.WriteString(entry)
	b.WriteByte('\n')

	if err := os.MkdirAll(filepath.Dir(excludePath), 0o755); err != nil {
