// retiredDenyRuleWarning is appended to the session-start banner for a repo
// whose agent permission config still carries the retired metadata deny rule.
// It reports and points at the fix; it does not repair. See the call site below
// for why nothing on the hook path writes that file.
//
// Deliberately short: it shares the banner with the agent-help pointer and any
// concurrent-session count.
const retiredDenyRuleWarning = "\n  A retired Entire permission rule in this repo is causing repeated" +
	"\n  approval prompts. Run 'entire doctor' to remove it."

type lifecycleHookHealthOps struct {
	check  func(context.Context) strategy.GitHookIntegrationHealth
	repair func(context.Context) error
}

var defaultLifecycleHookHealthOps = lifecycleHookHealthOps{
	check:  strategy.CheckGitHookIntegration,
	repair: strategy.EnsureSetup,
}

func lifecycleHookHealthFingerprint(health strategy.GitHookIntegrationHealth) string {
	data, _ := json.Marshal([4]string{string(health.Mode), string(health.State), health.Manager, health.ReasonCode})
	return string(data)
}

func lifecycleHookHealthWarning(health strategy.GitHookIntegrationHealth) string {
	if health.State == strategy.GitHookIntegrationCurrent {
		return ""
	}
	owner := string(health.Mode)
	if health.Manager != "" {
		owner += "/" + health.Manager
	}
	return fmt.Sprintf("Entire's Git hook integration is %s (%s). Run 'entire doctor' to diagnose and repair it.", health.State, owner)
}

// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
// fires state machine transition.
func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "session-start",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
		slog.String("model", event.Model),
	)

	if event.SessionID == "" {
		return fmt.Errorf("no session_id in %s event", event.Type)
	}
	if err := validation.ValidateSessionID(event.SessionID); err != nil {
		return fmt.Errorf("invalid %s event: %w", event.Type, err)
	}

	// Claim the session for this agent. First-writer-wins: subsequent agents
	// firing SessionStart for the same session ID are no-ops. Used by
	// InitializeSession (TurnStart) and the dispatcher skip in
	// DispatchLifecycleEvent for cross-agent disambiguation when Cursor IDE
	// forwards hooks to both .cursor/hooks.json and .claude/settings.json.
	if _, hintErr := strategy.StoreAgentTypeHint(ctx, event.SessionID, ag.Type()); hintErr != nil {
		logging.Warn(logCtx, "failed to store agent hint on session start",
			slog.String("error", hintErr.Error()))
	}

	// Resolve scope before the TurnStart prompt path.
