var defaultLifecycleHookHealthOps = lifecycleHookHealthOps{
	check:  strategy.CheckGitHookIntegration,
	repair: strategy.EnsureSetup,
}

func lifecycleHookHealthFingerprint(health strategy.GitHookIntegrationHealth) string {
	data, _ := json.Marshal([4]string{string(health.Mode), string(health.State), health.Manager, health.ReasonCode})
	return string(data)
}

func lifecycleHookHealthWarning(health strategy.GitHookIntegrationHealth) string {
	if health.State == strategy.GitHookIntegrationCurrent {
		return ""
	}
	owner := string(health.Mode)
	if health.Manager != "" {
		owner += "/" + health.Manager
	}
	return fmt.Sprintf("Entire's Git hook integration is %s (%s). Run 'entire doctor' to diagnose and repair it.", health.State, owner)
}

func loadPreviousHookHealthWarning(ctx context.Context, sessionID string, logCtx context.Context) string {
	hint, found, err := strategy.LoadHookHealthWarningHint(ctx, sessionID)
	if err != nil {
		// A corrupt/unreadable hint must fail open: returning no prior warning
		// makes the current condition visible instead of accidentally suppressing it.
		logging.Warn(logCtx, "failed to load hook health warning hint",
			slog.String("session_id", sessionID))
		return ""
	}
	if found {
		return hint
	}
	state, err := strategy.LoadSessionState(ctx, sessionID)
	if err != nil {
		logging.Warn(logCtx, "failed to load prior hook health warning",
			slog.String("session_id", sessionID))
		return ""
	}
	if state == nil {
		return ""
	}
	return state.LastHookHealthWarning
}

func repairLifecycleHookHealth(
	ctx context.Context,
	ag agent.Agent,
	sessionID, previous string,
	ops lifecycleHookHealthOps,
	logCtx context.Context,
) {
	repairErr := ops.repair(ctx)
	health := ops.check(ctx)
	if repairErr != nil && health.State == strategy.GitHookIntegrationCurrent {
		health.State = strategy.GitHookIntegrationError
		health.ReasonCode = "hook_repair_failed"
	}
	warning := lifecycleHookHealthWarning(health)
	if warning == "" {
		return
	}
	fingerprint := lifecycleHookHealthFingerprint(health)
	if fingerprint == previous {
		return
	}
	writer, ok := agent.AsHookResponseWriter(ag)
	if !ok {
		return
	}
	if err := writer.WriteHookResponse(warning); err != nil {
		logging.Warn(logCtx, "failed to write hook health warning",
			slog.String("session_id", sessionID),
			slog.String("mode", string(health.Mode)),
			slog.String("state", string(health.State)),
			slog.String("manager", health.Manager),
			slog.String("reason_code", health.ReasonCode))
		return
	}
	if err := strategy.StoreHookHealthWarningHint(ctx, sessionID, fingerprint); err != nil {
		logging.Warn(logCtx, "failed to store hook health warning hint",
			slog.String("session_id", sessionID),
			slog.String("mode", string(health.Mode)),
			slog.String("state", string(health.State)),
			slog.String("manager", health.Manager),
			slog.String("reason_code", health.ReasonCode))
	}
}

// handleLifecycleSessionStart handles session start: shows banner, checks concurrent sessions,
// fires state machine transition.
func handleLifecycleSessionStart(ctx context.Context, ag agent.Agent, event *agent.Event) error {
	logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
	logging.Info(logCtx, "session-start",
		slog.String("event", event.Type.String()),
		slog.String("session_id", event.SessionID),
		slog.String("session_ref", event.SessionRef),
		slog.String("model", event.Model),
	)

	if event.SessionID == "" {
		return fmt.Errorf("no session_id in %s event", event.Type)
	}
	if err := validation.ValidateSessionID(event.SessionID); err != nil {
		return fmt.Errorf("invalid %s event: %w", event.Type, err)
	}

func TestLifecycleHookHealthWarningUsesStableFingerprintAndSafeCopy(t *testing.T) {
	t.Parallel()
	health := strategy.GitHookIntegrationHealth{
		Mode: strategy.GitHookIntegrationLefthook, State: strategy.GitHookIntegrationError,
		Manager: "Lefthook", ReasonCode: "owned_entry_conflict", Reason: "secret prompt and commit message",
	}
	warning := lifecycleHookHealthWarning(health)
	require.Contains(t, warning, "Lefthook")
	require.Contains(t, warning, "error")
	require.Contains(t, warning, "entire doctor")
	require.NotContains(t, warning, health.Reason)

	first := lifecycleHookHealthFingerprint(health)
	health.Reason = "different free-form copy"
	require.Equal(t, first, lifecycleHookHealthFingerprint(health))
	health.ReasonCode = "different_code"
	require.NotEqual(t, first, lifecycleHookHealthFingerprint(health))
}

func TestLifecycleHookHealthRepairWarnsOnceThenAgainWhenFingerprintChanges(t *testing.T) {
	setupStopTestRepo(t)
	ctx := context.Background()
	const sessionID = "hook-health-dedup"
	ag := newMockHookResponseAgent()
	repairs := 0
	health := strategy.GitHookIntegrationHealth{
		Mode: strategy.GitHookIntegrationLefthook, State: strategy.GitHookIntegrationError,
		Manager: "Lefthook", ReasonCode: "conflict",
	}
	ops := lifecycleHookHealthOps{
		repair: func(context.Context) error { repairs++; return errors.New("sensitive repair detail") },
		check:  func(context.Context) strategy.GitHookIntegrationHealth { return health },
	}
	logCtx := logging.WithComponent(ctx, "test")

	repairLifecycleHookHealth(ctx, ag, sessionID, "", ops, logCtx)
	require.Equal(t, 1, repairs)
	require.Contains(t, ag.lastMessage, "entire doctor")
	first, found, err := strategy.LoadHookHealthWarningHint(ctx, sessionID)
	require.NoError(t, err)
	require.True(t, found)

	ag.lastMessage = ""
	repairLifecycleHookHealth(ctx, ag, sessionID, first, ops, logCtx)
	require.Equal(t, 2, repairs, "repair is attempted on every turn")
	require.Empty(t, ag.lastMessage, "same fingerprint is warned only once")

	health.ReasonCode = "changed-conflict"
	repairLifecycleHookHealth(ctx, ag, sessionID, first, ops, logCtx)
	require.Equal(t, 3, repairs)
	require.Contains(t, ag.lastMessage, "entire doctor", "changed failures warn again")
}

func TestLifecycleHookHealthHintPrecedesPersistedState(t *testing.T) {
	setupStopTestRepo(t)
	ctx := context.Background()
	const sessionID = "hook-health-precedence"
	require.NoError(t, strategy.SaveSessionState(ctx, &strategy.SessionState{
		SessionID: sessionID, BaseCommit: "abc", StartedAt: time.Now(), LastHookHealthWarning: "state-value",
	}))
	const hint = `["lefthook","error","Lefthook","newer"]`
	require.NoError(t, strategy.StoreHookHealthWarningHint(ctx, sessionID, hint))
	require.Equal(t, hint, loadPreviousHookHealthWarning(ctx, sessionID, logging.WithComponent(ctx, "test")))
}

// TestHandleLifecycleSessionStart_StoresAgentTypeHint verifies the
// SessionStart hook claims the session for its agent so a wrapper agent's
// later TurnStart hook (e.g., Cursor IDE forwarding to Claude Code's hook
// system) cannot re-label the session.
func TestHandleLifecycleSessionStart_StoresAgentTypeHint(t *testing.T) {
	setupStopTestRepo(t)

	ag := newMockHookResponseAgent()
	ag.agentType = agent.AgentTypeCursor
	event := &agent.Event{
		Type:      agent.SessionStart,
		SessionID: "test-agent-hint",
		Timestamp: time.Now(),
	}
	require.NoError(t, handleLifecycleSessionStart(context.Background(), ag, event))

	got := strategy.LoadAgentTypeHint(context.Background(), "test-agent-hint")
	require.Equal(t, agent.AgentTypeCursor, got)
}

// TestHandleLifecycleSessionStart_AgentTypeHintFirstWriterWins verifies that
// when multiple agents fire SessionStart for the same session ID, only the
// first agent's claim is recorded AND only the first emits the banner. This
// matches both the Cursor cross-agent and the Gemini repeat-source
// (startup → resume) cases — the user must see the banner only once.
func TestHandleLifecycleSessionStart_AgentTypeHintFirstWriterWins(t *testing.T) {
	setupStopTestRepo(t)

	ctx := context.Background()
	sessionID := "test-agent-hint-race"

	first := newMockHookResponseAgent()
	first.agentType = agent.AgentTypeCursor
	require.NoError(t, handleLifecycleSessionStart(ctx, first, &agent.Event{
		Type: agent.SessionStart, SessionID: sessionID, Timestamp: time.Now(),
	}))
	require.NotEmpty(t, first.lastMessage, "first SessionStart must emit the banner")

	second := newMockHookResponseAgent()
	second.agentType = agent.AgentTypeClaudeCode
	require.NoError(t, handleLifecycleSessionStart(ctx, second, &agent.Event{
		Type: agent.SessionStart, SessionID: sessionID, Timestamp: time.Now(),
	}))
	require.Empty(t, second.lastMessage, "subsequent SessionStarts for the same session must not emit the banner again")

