type lifecycleHookHealthOps struct {
	check  func(context.Context) strategy.GitHookIntegrationHealth
	repair func(context.Context) error
}

var defaultLifecycleHookHealthOps = lifecycleHookHealthOps{
	check:  strategy.CheckGitHookIntegration,
	repair: strategy.EnsureSetup,
}

func lifecycleHookHealthFingerprint(health strategy.GitHookIntegrationHealth) string {
	data, err := json.Marshal([4]string{string(health.Mode), string(health.State), health.Manager, health.ReasonCode})
	if err != nil {
		return "" // [4]string is always JSON-encodable; retain fail-open behavior if that changes.
	}
	return string(data)
}

func lifecycleHookHealthWarning(health strategy.GitHookIntegrationHealth) string {
	if health.State == strategy.GitHookIntegrationCurrent {
		return ""
	}
	owner := string(health.Mode)
	if health.Manager != "" {
		owner += "/" + health.Manager
	}
	return fmt.Sprintf("Entire's Git hook integration is %s (%s). Run 'entire doctor' to diagnose and repair it.", health.State, owner)
}

func loadPreviousHookHealthWarning(ctx context.Context, sessionID string) string {
	hint, found, err := strategy.LoadHookHealthWarningHint(ctx, sessionID)
	if err != nil {
		// A corrupt/unreadable hint must fail open: returning no prior warning
		// makes the current condition visible instead of accidentally suppressing it.
		logging.Warn(ctx, "failed to load hook health warning hint",
			slog.String("session_id", sessionID))
		return ""
	}
	if found {
		return hint
	}
	state, err := strategy.LoadSessionState(ctx, sessionID)
	if err != nil {
		logging.Warn(ctx, "failed to load prior hook health warning",
			slog.String("session_id", sessionID))
		return ""
	}
	if state == nil {
		return ""
	}
	return state.LastHookHealthWarning
}

func repairLifecycleHookHealth(
	ctx context.Context,
	ag agent.Agent,
	sessionID, previous string,
	ops lifecycleHookHealthOps,
) {
	repairErr := ops.repair(ctx)
	health := ops.check(ctx)
	if repairErr != nil && health.State == strategy.GitHookIntegrationCurrent {
		health.State = strategy.GitHookIntegrationError
		health.ReasonCode = "hook_repair_failed"
	}
	if repairErr != nil || health.State != strategy.GitHookIntegrationCurrent {
		// Do not log repairErr or health.Reason here: setup errors can include
		// repository content. Stable classification fields are sufficient for
		// diagnosis without leaking prompts, files, or commit messages.
		logging.Warn(ctx, "git hook integration repair incomplete",
			slog.String("session_id", sessionID),
			slog.String("mode", string(health.Mode)),
			slog.String("state", string(health.State)),
			slog.String("manager", health.Manager),
			slog.String("reason_code", health.ReasonCode))
	}
	warning := lifecycleHookHealthWarning(health)
	if warning == "" {
		return
	}
	fingerprint := lifecycleHookHealthFingerprint(health)
	if fingerprint == previous {
		return
	}
	writer, ok := agent.AsHookResponseWriter(ag)
	if !ok {
		return
	}
	if err := writer.WriteHookResponse(warning); err != nil {
		logging.Warn(ctx, "failed to write hook health warning",
			slog.String("session_id", sessionID),
			slog.String("mode", string(health.Mode)),
			slog.String("state", string(health.State)),
			slog.String("manager", health.Manager),
			slog.String("reason_code", health.ReasonCode))
		return
	}
	if err := strategy.StoreHookHealthWarningHint(ctx, sessionID, fingerprint); err != nil {
		logging.Warn(ctx, "failed to store hook health warning hint",
			slog.String("session_id", sessionID),
			slog.String("mode", string(health.Mode)),
			logging.Warn(logging.WithComponent(ctx, "session"), "failed to read model hint file",
				slog.String("session_id", sessionID),
				slog.Any("error", err))
		}
		return ""
	}
	return strings.TrimSpace(string(data))
}

const hookHealthHintSuffix = ".hook-health"

// StoreHookHealthWarningHint atomically records the warning fingerprint shown
// before SessionState exists. The per-session gate serializes it with transfer.
func StoreHookHealthWarningHint(ctx context.Context, sessionID, fingerprint string) error {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return fmt.Errorf("invalid session ID: %w", err)
	}
	if !validHookHealthWarningFingerprint(fingerprint) {
		return errors.New("invalid hook health warning fingerprint")
	}
	_, _, release, err := acquireSessionGate(ctx, sessionID)
	if err != nil {
		return err
	}
	defer release()
	root, err := openSessionStateRoot(ctx)
	if err != nil {
		return err
	}
	defer root.Close()
	if err := jsonutil.WriteFileAtomicIn(root, sessionID+hookHealthHintSuffix, []byte(fingerprint), 0o600); err != nil {
		return fmt.Errorf("failed to write hook health warning hint: %w", err)
	}
	return nil
}

// LoadHookHealthWarningHint returns a pending warning fingerprint. Malformed
// content is an error so lifecycle fails open by warning instead of suppressing.
func LoadHookHealthWarningHint(ctx context.Context, sessionID string) (string, bool, error) {
	if err := validation.ValidateSessionID(sessionID); err != nil {
		return "", false, fmt.Errorf("invalid session ID: %w", err)
	}
	root, err := openSessionStateRootForRead(ctx)
	if err != nil {
		return "", false, err
	}
	if root == nil {
		return "", false, nil
	}
	defer root.Close()
	data, err := osroot.ReadFileNoFollow(root, sessionID+hookHealthHintSuffix)
	if os.IsNotExist(err) {
		return "", false, nil
	}
	if err != nil {
		return "", false, fmt.Errorf("read hook health warning hint: %w", err)
	}
	fingerprint := strings.TrimSpace(string(data))
	if !validHookHealthWarningFingerprint(fingerprint) {
		return "", false, errors.New("invalid hook health warning hint")
	}
	return fingerprint, true, nil
}

func validHookHealthWarningFingerprint(fingerprint string) bool {
	var fields []string
	return json.Unmarshal([]byte(fingerprint), &fields) == nil && len(fields) == 4
}

// TransferHookHealthWarningHint copies a pending pre-state warning into the
// durable session state and consumes the hint while holding the session gate.
func TransferHookHealthWarningHint(ctx context.Context, sessionID string) error {
	_, _, release, err := acquireSessionGate(ctx, sessionID)
	if err != nil {
		return err
	}
	defer release()
	fingerprint, found, err := LoadHookHealthWarningHint(ctx, sessionID)
	if err != nil || !found {
		return err
	}
	state, err := LoadSessionState(ctx, sessionID)
	if err != nil {
		return err
	}
	if state == nil {
		return ErrStateNotFound
	}
	state.LastHookHealthWarning = fingerprint
	if err := SaveSessionState(ctx, state); err != nil {
		return err
	}
	root, err := openSessionStateRootForRead(ctx)
	if err != nil {
		return err
	}
	if root == nil {
		return nil
	}
	defer root.Close()
	if err := osroot.RemoveNoSymlinks(root, sessionID+hookHealthHintSuffix); err != nil && !os.IsNotExist(err) {
		return fmt.Errorf("consume hook health warning hint: %w", err)
	}
	return nil
}

// StoreAgentTypeHint records the agent type that owns a session before
// SessionState exists. Used by the lifecycle dispatcher when SessionStart fires
// (state isn't created until TurnStart, so we need a place to remember which
// agent claimed the session first).
//
// Semantics: first writer wins. When multiple agents fire hooks for the same
// session ID — e.g., Cursor IDE running cursor-agent while also forwarding to
// Claude Code's hook system — only the agent that fires SessionStart first
// gets recorded. Subsequent calls return nil without overwriting.
//
// At TurnStart, InitializeSession reads this hint to override agentType when
// the hook firing isn't the same agent that owns the session. After the state
// file is written, the hint is unused but remains until ClearSessionState
// removes it alongside the state file.
//

	// TurnID is a unique identifier for the current agent turn.
	// Lifecycle:
	//   - Generated fresh in InitializeSession at each turn start
	//   - Shared across all checkpoints within the same turn
	//   - Used to correlate related checkpoints when a turn's work spans multiple commits
	//   - Persists until the next InitializeSession call generates a new one
	TurnID string `json:"turn_id,omitempty"`

	// TurnCheckpointIDs tracks all checkpoint IDs condensed during the current turn.
	// Lifecycle:
	//   - Set in PostCommit when a checkpoint is condensed for an ACTIVE session
	//   - Consumed in HandleTurnEnd to finalize all checkpoints with the full transcript
	//   - Cleared in HandleTurnEnd after finalization completes
	//   - Cleared in InitializeSession when a new prompt starts
	//   - Cleared when session is reset (ResetSession deletes the state file entirely)
	TurnCheckpointIDs []string `json:"turn_checkpoint_ids,omitempty"`

	// LastInteractionTime is updated on agent-interaction events (TurnStart,
	// TurnEnd, SessionStop, Compaction) but NOT on git commit hooks.
	// Used for stale session detection in "entire doctor".
	LastInteractionTime *time.Time `json:"last_interaction_time,omitempty"`

	// CaptureDegradedAt records when the session's most recent turn degraded
	// capture because a worktree status scan breached its budget (new-file
	// detection skipped, or the checkpoint itself skipped). Set at turn end,
	// cleared by the next turn whose scans stay within budget. Surfaced as a
	// warning by `entire status`.
	CaptureDegradedAt *time.Time `json:"capture_degraded_at,omitempty"`

	// LastHookHealthWarning is the stable health fingerprint most recently
	// shown to this session. Human-readable warning copy is deliberately not
	// persisted so copy changes do not cause repeated warnings.
	LastHookHealthWarning string `json:"last_hook_health_warning,omitempty"`

	// StepCount is the number of checkpoints/steps created in this session.
	// JSON tag kept as "checkpoint_count" for backward compatibility with existing state files.
	StepCount int `json:"checkpoint_count"`

	// CheckpointTranscriptStart is the transcript line offset where the current
	// checkpoint cycle began. Set to 0 at session start, updated to current
	// transcript length after each condensation. Used to scope the transcript
	// for checkpoint condensation: "everything since last checkpoint".
	CheckpointTranscriptStart int `json:"checkpoint_transcript_start,omitempty"`

	// CheckpointTranscriptSize is the byte size of the transcript at last condensation.
	// Used for fast "has new content?" checks in PostCommit: compare the git blob size
	// against this value without reading the full transcript content.
	CheckpointTranscriptSize int64 `json:"checkpoint_transcript_size,omitempty"`

	// Deprecated: CondensedTranscriptLines is replaced by CheckpointTranscriptStart.
	// Kept for backward compatibility with existing state files.
	// Use NormalizeAfterLoad() to migrate.
	CondensedTranscriptLines int `json:"condensed_transcript_lines,omitempty"`

	// UntrackedFilesAtStart tracks files that existed at session start (so they are
	// not attributed to the session)
	UntrackedFilesAtStart []string `json:"untracked_files_at_start,omitempty"`

	// FilesTouched tracks files modified/created/deleted during this session
	FilesTouched []string `json:"files_touched,omitempty"`

