func looksLikeLefthookHook(data []byte, hook string) bool {
	content := string(data)
	return strings.HasPrefix(content, "#!/bin/sh\n\nif [ \"$LEFTHOOK_VERBOSE\" = \"1\" -o \"$LEFTHOOK_VERBOSE\" = \"true\" ]; then\n") &&
		strings.Contains(content, "\nif [ \"$LEFTHOOK\" = \"0\" ]; then\n  exit 0\nfi\n") &&
		strings.Contains(content, "\ncall_lefthook()\n{\n") &&
		strings.HasSuffix(strings.TrimSpace(content), "call_lefthook run \""+hook+"\" \"$@\"")
}

// RemoveGitHookIntegration removes only artifacts whose exact ownership marker
